function ColorField({label,value,onChange}:{label:string;value:string;onChange:(value:string)=>void}){return <label className="color-field"><span>{label}</span><input type="color" value={value} onChange={event=>onChange(event.target.value)}/><code>{value.toUpperCase()}</code></label>}
function FleetNumberControl({buses,renameBus}:{buses:B[];renameBus:(id:string,number:string)=>boolean}){const ordered=[...buses].sort((a,b)=>a.n.localeCompare(b.n,undefined,{numeric:true})),[selectedId,setSelectedId]=useState(ordered[0]?.id||""),selected=ordered.find(bus=>bus.id===selectedId)||ordered[0],[number,setNumber]=useState(selected?.n||"");const choose=(id:string)=>{setSelectedId(id);setNumber(ordered.find(bus=>bus.id===id)?.n||"")};return <section className="settings-group fleet-number-control"><h3>FLEET NUMBER CONTROL</h3><p>Bus numbers are protected in the regular editor. Use this controlled area only for an authorized fleet-number correction.</p>{selected?<div className="fleet-number-row"><label>SELECT BUS<select value={selected.id} onChange={event=>choose(event.target.value)}>{ordered.map(bus=><option value={bus.id} key={bus.id}>Bus {bus.n||"New"} — {ST[bus.s][0]}</option>)}</select></label><label>AUTHORIZED NEW NUMBER<input inputMode="numeric" value={number} onChange={event=>setNumber(event.target.value.replace(/\D/g,""))}/></label><button type="button" onClick={()=>{if(renameBus(selected.id,number))setNumber(number.trim())}}>UPDATE NUMBER</button></div>:<p>No buses are available.</p>}<div className="fleet-warning">Changing a fleet number is a protected administrative action. Duplicate numbers are blocked.</div></section>}
function StatusSettings({buses,renameBus,colors,setColors,visuals,setVisuals,themeName,setThemeName,applyTheme,exportBoard,importBoard,close}:{buses:B[];renameBus:(id:string,number:string)=>boolean;colors:Record<S,string>;setColors:React.Dispatch<React.SetStateAction<Record<S,string>>>;visuals:Visuals;setVisuals:React.Dispatch<React.SetStateAction<Visuals>>;themeName:string;setThemeName:(value:string)=>void;applyTheme:(name:string)=>void;exportBoard:()=>void;importBoard:(event:React.ChangeEvent<HTMLInputElement>)=>void;close:()=>void}){
 const manualVisual=(key:Exclude<keyof Visuals,"sections">,value:string)=>{setThemeName("custom");setVisuals(current=>({...current,[key]:value}))};
 const manualSection=(key:SectionThemeKey,value:string)=>{setThemeName("custom");setVisuals(current=>({...current,sections:{...current.sections,[key]:value}}))};
 const manualStatus=(status:S,value:string)=>{setThemeName("custom");setColors(current=>({...current,[status]:value}))};
 const globalFields=[["page","Page Background"],["panel","Panel Background"],["text","Main Text"],["header","Header Background"],["headerText","Header Text"],["title","Section Title Text"],["border","Borders / Lines"],["slot","Parking Spaces"],["command","Command Bar"],["commandText","Command Text"]] as const;
 return <div className="shade settings-shade" onMouseDown={event=>{if(event.target===event.currentTarget)close()}}><section className="settings-modal"><div className="mhead"><span>ADMINISTRATIVE SETTINGS<h2>Dashboard Settings</h2></span><button onClick={close}>X</button></div><div className="settings-body"><section className="settings-group board-data"><h3>BOARD BACKUP &amp; TRANSFER</h3><p>Move this device's complete board to another browser, Home Screen app, iPad, or phone. Export first, then import that file on the destination device.</p><div><button type="button" onClick={exportBoard}>EXPORT / SHARE BACKUP</button><label>IMPORT BACKUP<input type="file" accept=".json,application/json" onChange={importBoard}/></label></div><small>Import replaces the destination device's current board only after you confirm it.</small></section><FleetNumberControl buses={buses} renameBus={renameBus}/><section className="settings-group"><h3>THEMES</h3><p>Apply a complete dashboard and bus-color preset. You can fine-tune anything below.</p><div className="theme-grid">{Object.entries(THEMES).map(([key,preset])=><button className={themeName===key?"active":""} key={key} onClick={()=>applyTheme(key)}><i style={{background:preset.visuals.page,borderColor:preset.visuals.border}}/><b>{preset.label}</b></button>)}</div>{themeName==="custom"&&<div className="custom-theme-badge">CUSTOM MANUAL COLORS</div>}</section><section className="settings-group"><h3>MANUAL DASHBOARD COLORS</h3><div className="manual-grid">{globalFields.map(([key,label])=><ColorField key={key} label={label} value={visuals[key]} onChange={value=>manualVisual(key,value)}/>)}</div></section><section className="settings-group"><h3>SECTION BACKGROUNDS</h3><div className="manual-grid section-color-grid">{SECTION_THEME_KEYS.map(([key,label])=><ColorField key={key} label={label} value={visuals.sections[key]} onChange={value=>manualSection(key,value)}/>)}</div></section><section className="settings-group"><h3>BUS STATUS COLORS</h3><div className="manual-grid status-color-grid">{(Object.keys(ST) as S[]).map(status=><label className="color-field status-field" key={status}><span><Icon s={status}/>{ST[status][0]}</span><input type="color" value={colors[status]} onChange={event=>manualStatus(status,event.target.value)}/><code>{colors[status].toUpperCase()}</code></label>)}</div></section></div><div className="settings-actions"><button onClick={()=>applyTheme("default")}>RESET ALL</button><button className="save" onClick={close}>DONE</button></div></section></div>}
function RemoveBusPicker({name,buses,close,remove}:{name:string;buses:B[];close:()=>void;remove:(id:string)=>void}){return <div className="shade remove-shade" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><section className="remove-modal"><div className="mhead"><span>SECTION BUSES<h2>{name}</h2></span><button onClick={close}>X</button></div><div className="remove-list">{buses.length===0?<p>No buses are currently assigned to this section.</p>:buses.map(bus=><div key={bus.id}><span><Icon s={bus.s}/><b>Bus {bus.n||"New"}</b><small>{ST[bus.s][0]}</small></span><button onClick={()=>remove(bus.id)}>REMOVE</button></div>)}</div><div className="settings-actions"><span/><button className="save" onClick={close}>DONE</button></div></section></div>}
